// ---------- MATT: holographic architecture ----------
// Scenes are driven off the global clock T (which always advances) rather than
// an accumulated dt, so they self-expire even through super-freeze/hitstop.
function mattTower(f){
  const d=f.facing;
  game.mattTower={t0:T,life:0.9,x:f.x+d*112,dir:d};
  addShake(8,.3); SFX.hitH();
  for(let i=0;i<14;i++){
    spawn({type:'shard',x:f.x+d*112+rnd(-26,26),y:GROUND-rnd(0,150),a:rnd(0,7),
      vx:rnd(-40,40),vy:-rnd(120,420),life:rnd(.35,.7),size:rnd(12,30),
      col:i%2?'#3fd8ff':'#7affd4',layer:1});
  }
}
function drawMattTower(){
  const S=game.mattTower; if(!S)return;
  const k=(T-S.t0)/S.life;
  if(k>=1){ game.mattTower=null; return; }
  const h=340*Math.min(1,k*2.4), a=Math.min(1,(1-k)*2.2);
  ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=a*0.85;
  ctx.strokeStyle='#3fd8ff'; ctx.lineWidth=2; ctx.shadowColor='#3fd8ff'; ctx.shadowBlur=12;
  const w=74, x=S.x-w/2, base=GROUND;
  for(let i=0;i<7;i++){ const y=base-h*(i/6);
    ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x+w,y); ctx.stroke(); }
  ctx.beginPath(); ctx.moveTo(x,base); ctx.lineTo(x,base-h);
  ctx.moveTo(x+w,base); ctx.lineTo(x+w,base-h); ctx.stroke();
  ctx.globalAlpha=a*0.30; ctx.fillStyle='#3fd8ff';
  ctx.fillRect(x,base-h,w,h);
  ctx.restore();
}
function mattMasterPlan(f){
  const o=other(f), d=Math.sign(o.x-f.x)||f.facing;
  game.mattPlan={t0:T,life:1.6,dir:d};
  addFlash('#dffaff',.45); addShake(11,.45); SFX.superGo();
  for(let i=0;i<9;i++){
    projs.push({owner:f,type:'bprint',x:f.x+d*44,y:f.y-40-rnd(0,96),vx:(430+rnd(0,170))*d,
      vy:rnd(-40,40),dmg:32,kx:150,ky:-180,stun:.4,t:0,dead:false,low:false});
  }
}
function drawMattPlanScene(){
  const S=game.mattPlan; if(!S)return;
  const k=(T-S.t0)/S.life;
  if(k>=1){ game.mattPlan=null; return; }
  const a=Math.sin(Math.min(1,k)*Math.PI);
  ctx.save(); ctx.globalCompositeOperation='lighter';
  // drafting grid sweeps across the arena
  ctx.globalAlpha=a*0.34; ctx.strokeStyle='#3fd8ff'; ctx.lineWidth=1;
  const off=(T*90)%56;
  for(let x=-56+off;x<W;x+=56){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for(let y=(T*40)%56;y<H;y+=56){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  // rising skyline of wireframe towers
  ctx.globalAlpha=a*0.6; ctx.lineWidth=2; ctx.shadowColor='#3fd8ff'; ctx.shadowBlur=10;
  for(let i=0;i<7;i++){
    const bx=70+i*130, bw=70, prog=clamp(k*2.1-i*0.12,0,1);
    if(prog<=0)continue;
    const bh=(90+((i*37)%120))*prog;
    ctx.strokeRect(bx,GROUND-bh,bw,bh);
    for(let r=1;r<4;r++){ const yy=GROUND-bh*(r/4);
      ctx.beginPath(); ctx.moveTo(bx,yy); ctx.lineTo(bx+bw,yy); ctx.stroke(); }
  }
  ctx.restore();
}
